let Obj = [];
let colors = ['#EE7485', '#FCB500', '#007EB6', '#232524', '#009135', '#E94015'];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	addObj();
}

function draw() {
	background('#FFF4D3');
	for (let i of Obj) {
		i.show();
		i.move();
	}
}

function addObj() {
	let wid = width * 0.85;
	let c = 12;
	let w = wid / c;
	for (let i = 0; i < c; i++) {
		for (let j = 0; j < c; j++) {
			let x = i * w + (w / 2) + (width - wid) / 2;
			let y = j * w + (w / 2) + (width - wid) / 2;
			let dst = dist(x, y, width/2, height/2);
			let t = map(dst, 0, sqrt(sq(width/2) + sq(height/2)), 0, 80);
			Obj.push(new ECH(x, y, w * 0.4, random(10), -int(t)));
		}
	}
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

class ECH {
	constructor(x, y, d, a, t) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.a = a;
		this.offset = 0;
		this.col1 = this.col2 = '🦂';
		while (this.col1 == this.col2) {
			this.col1 = random(colors);
			this.col2 = random(colors);
		}
		this.maxOff = this.d * 1.5;
		this.t = t;
		this.t1 = 40;
		this.t2 = this.t1 + 60;
		this.t3 = this.t2 + 40;
	}

	show() {
		cyli(this.x, this.y, this.d, this.a, this.offset, this.col1, this.col2);
	}

	move() {
		if (0 < this.t && this.t < this.t1) {
			let n = norm(this.t, 0, this.t1 - 1);
			this.offset = lerp(0, this.maxOff, easeInOutQuart(n));
		} else if (this.t2 < this.t && this.t < this.t3) {
			let n = norm(this.t, this.t2, this.t3 - 1);
			this.offset = lerp(this.maxOff, 0, easeInOutQuart(n));
		}
		this.t++;

		if (this.t3 < this.t) {
			this.init();
		}
	}

	init() {
		this.t = -30;
		this.a = random(10);
		this.col1 = this.col2 = '🦂';
		while (this.col1 == this.col2) {
			this.col1 = random(colors);
			this.col2 = random(colors);
		}
	}
}

function cyli(x, y, d, ang, off, col1, col2) {
	push();
	translate(x, y);
	rotate(ang);
	fill(col1);
	beginShape();
	for (let a = -HALF_PI; a < -HALF_PI + PI; a += PI / 45) {
		vertex((off / 2) + d * 0.5 * cos(a), d * 0.5 * sin(a));
	}

	for (let a = -HALF_PI + PI; a > -HALF_PI; a -= PI / 45) {
		vertex(-(off / 2) + d * 0.5 * cos(a), d * 0.5 * sin(a));
	}
	endShape(CLOSE);

	fill(col2);
	beginShape();
	for (let a = HALF_PI; a < HALF_PI + PI; a += PI / 45) {
		vertex((off / 2) + d * 0.5 * cos(a), d * 0.5 * sin(a));
	}

	for (let a = HALF_PI + PI; a > HALF_PI; a -= PI / 45) {
		vertex(-(off / 2) + d * 0.5 * cos(a), d * 0.5 * sin(a));
	}
	endShape(CLOSE);
	pop();
}

